async Task<int> GetTemperatureAsync(string city)
{
    await Task.Delay(300);
    return city.Length * 3;
}

var cities = new[] { "Amman", "Cairo", "Riyadh" };
var sw = System.Diagnostics.Stopwatch.StartNew();

foreach (var c in cities)
    Console.WriteLine(await GetTemperatureAsync(c));
Console.WriteLine($"Sequential: {sw.ElapsedMilliseconds} ms");

sw.Restart();
var tasks = cities.Select(GetTemperatureAsync).ToList();
var temps = await Task.WhenAll(tasks);
Console.WriteLine($"WhenAll: {sw.ElapsedMilliseconds} ms -> {string.Join(", ", temps)}");

async Task<int> SlowAsync(int ms) { await Task.Delay(ms); return ms; }

var sw = System.Diagnostics.Stopwatch.StartNew();
var a = await SlowAsync(400);
var b = await SlowAsync(400);
Console.WriteLine($"Sequential: {a + b} in ~{sw.ElapsedMilliseconds} ms");

sw.Restart();
var both = await Task.WhenAll(SlowAsync(400), SlowAsync(400));
Console.WriteLine($"WhenAll: {both.Sum()} in ~{sw.ElapsedMilliseconds} ms");

// Timeout: give up after 100 ms
try { await SlowAsync(2000).WaitAsync(TimeSpan.FromMilliseconds(100)); }
catch (TimeoutException) { Console.WriteLine("Timed out!"); }
